  per_user = for u in users {
    a = boundary retry 2 { return get_availability({ user_id: u.id, date: d }) } catch err { return fail("AVAIL_FAILED", err.message) }
    return { user_id: u.id, busy: a.busy if a.busy != null else [] }
  }
  return { date: d, per_user: per_user }
}
starts_min = list.range(540, 961, 30)   # 540..960 step 30
candidates = for day in avails {
  base = time.parse(day.date + "T00:00:00Z")
  slots = for sm in starts_min {
    s = base + sm * 60000
    e = s + 3600000
    ok = fold acc = true for pu in day.per_user {
